"""Facts about this machine, and the gates a benchmark run must pass before it is allowed to produce a record.

Run it alone to see what a record would say about the machine:

  python harness/preflight.py --basal-repo ~/repos/current/basal
  python harness/preflight.py --basal-repo ~/repos/current/basal --benchmarking   # adds the AC-power gate

Gates (--benchmarking only, since setup may legitimately run on battery):
  AC power          a fanless M4 Air throttles differently on battery; a record measured there is not comparable
  Metal reachable   torch MPS and MLX must see the GPU, which a sandboxed shell denies
  weights cache     HF_HOME must exist and be writable
"""
import argparse
import json
import os
import platform
import shutil
import subprocess
import sys
from pathlib import Path


def _run(argv: list[str]) -> str:
    try:
        return subprocess.run(argv, capture_output=True, text=True, timeout=30).stdout.strip()
    except (OSError, subprocess.SubprocessError):
        return ""


def hardware() -> dict:
    """Chip, cores and memory from system_profiler, which works where `sysctl hw.memsize` is blocked."""
    out = _run(["system_profiler", "-json", "SPHardwareDataType"])
    item = {}
    if out:
        try:
            item = json.loads(out)["SPHardwareDataType"][0]
        except (ValueError, KeyError, IndexError):
            item = {}
    return {"model": item.get("machine_model"), "chip": item.get("chip_type"),
            "cores": item.get("number_processors"), "memory": item.get("physical_memory"),
            "macos": platform.mac_ver()[0] or platform.release(), "arch": platform.machine()}


def power() -> dict:
    text = _run(["pmset", "-g", "batt"])
    return {"source": "AC" if "AC Power" in text else "battery" if text else "unknown", "raw": text.splitlines()[:1]}


def disk(paths: list[Path]) -> dict:
    out = {}
    for p in paths:
        try:
            usage = shutil.disk_usage(p)
            out[str(p)] = {"free_gb": round(usage.free / 2**30, 1), "total_gb": round(usage.total / 2**30, 1)}
        except OSError as e:
            out[str(p)] = {"error": str(e)}
    return out


def python_stack(python: str) -> dict:
    """Versions and Metal reachability, asked of the interpreter that will run the benchmarks, not of this one."""
    probe = ("import json,sys,platform;d={'python':platform.python_version(),'arch':platform.machine()}\n"
             "import torch;d['torch']=torch.__version__;d['mps']=torch.backends.mps.is_available()\n"
             "import transformers;d['transformers']=transformers.__version__\n"
             "try:\n import mlx.core as mx;d['mlx']=mx.__version__;d['mlx_gpu']=str(mx.default_device())\n"
             "except Exception as e: d['mlx_error']=f'{type(e).__name__}: {e}'\n"
             "try:\n import llama_cpp;d['llama_cpp']=llama_cpp.__version__\n"
             "except Exception as e: d['llama_cpp_error']=f'{type(e).__name__}: {e}'\n"
             "print(json.dumps(d))")
    out = _run([python, "-c", probe])
    try:
        return json.loads(out.splitlines()[-1])
    except (ValueError, IndexError):
        return {"error": "could not probe the benchmark interpreter", "raw": out[-400:]}


def hf_home() -> dict:
    home = os.environ.get("HF_HOME")
    if not home:
        return {"path": None, "writable": False, "why": "HF_HOME is not set"}
    p = Path(home)
    probe = p / ".basal-bench-write-probe"
    try:
        p.mkdir(parents=True, exist_ok=True)
        probe.touch()
        probe.unlink()
        writable = True
        why = None
    except OSError as e:
        writable, why = False, str(e)
    return {"path": home, "exists": p.exists(), "writable": writable, "why": why}


def git_facts(repo: Path) -> dict:
    head = _run(["git", "-C", str(repo), "rev-parse", "HEAD"])
    return {"repo": str(repo), "head": head,
            "upstream_main": _run(["git", "-C", str(repo), "rev-parse", "upstream/main"]),
            "dirty": bool(_run(["git", "-C", str(repo), "status", "--porcelain"])),
            "remotes": _run(["git", "-C", str(repo), "remote", "-v"]).splitlines()}


def collect(basal_repo: Path, python: str) -> dict:
    return {"hardware": hardware(), "power": power(), "stack": python_stack(python),
            "hf_home": hf_home(), "git": git_facts(basal_repo), "benchmark_python": python,
            "disk": disk([Path.home(), Path(os.environ.get("HF_HOME") or Path.home())])}


def gates(env: dict, benchmarking: bool) -> list[str]:
    """The reasons this machine must not produce a record right now. Empty means it may."""
    failures = []
    stack = env["stack"]
    if env["hardware"]["arch"] != "arm64":
        failures.append(f"architecture is {env['hardware']['arch']}, not arm64 (a Rosetta shell)")
    if not env["hf_home"]["writable"]:
        failures.append(f"HF_HOME is not writable: {env['hf_home'].get('why')}")
    if not benchmarking:
        return failures
    if env["power"]["source"] != "AC":
        failures.append(f"power source is {env['power']['source']}, not AC; throttling makes the record "
                        "incomparable")
    if not stack.get("mps"):
        failures.append("torch cannot reach Metal (torch.backends.mps.is_available() is False); run outside the "
                        "Bash sandbox")
    if "mlx_error" in stack:
        failures.append(f"MLX cannot reach the GPU: {stack['mlx_error']}; run outside the Bash sandbox")
    return failures


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--basal-repo", required=True, type=Path)
    ap.add_argument("--python", default=str(Path.home() / "basal-env/bin/python"))
    ap.add_argument("--benchmarking", action="store_true", help="also apply the gates a measured record needs")
    ap.add_argument("--out", type=Path, default=None)
    a = ap.parse_args()
    env = collect(a.basal_repo, a.python)
    failed = gates(env, a.benchmarking)
    env["gates"] = {"benchmarking": a.benchmarking, "failures": failed, "passed": not failed}
    text = json.dumps(env, indent=1, sort_keys=True)
    if a.out:
        a.out.parent.mkdir(parents=True, exist_ok=True)
        a.out.write_text(text + "\n", encoding="utf-8")
    print(text)
    for why in failed:
        print(f"preflight: {why}", file=sys.stderr)
    return 1 if failed else 0


if __name__ == "__main__":
    raise SystemExit(main())
