                gguf_path: Path | None = None) -> list[str]:
    """Option-order sensitivity: how often the top pick flips, and what averaging over K orders buys."""
    resolved = _mode_args(unit, (mode,), gguf_path)
    return [python, "-m", "basal.bench", "--order-check", "--model", unit.model, "--mode", resolved[0],
