input.content:
"""Turning two sets of measurements into a defensible statement.

Pure functions only. The hard part is not arithmetic, it is refusing to call noise an improvement: this machine is a
fanless MacBook Air, and its run-to-run drift is routinely larger than the optimisations being measured. So:

  noise floor    per side, (max - min) / median over that side's repeats
  threshold      max(the louder side's noise floor, MIN_RELATIVE_CHANGE)
  BETTER/WORSE   only when the median moved further than the threshold, in the metric's own good direction

Correctness is handled by gates, not by thresholds. A gate failure makes the whole record BROKEN whatever the
latency did, because a faster engine that decides differently has not been optimised, it has been changed.
"""
import statistics
from dataclasses import dataclass, field
from enum import Enum

from config import AGREE_GATE, MEMORY_TOLERANCE, MIN_RELATIVE_CHANGE, Direction, TIMING_METRICS

# Metrics the overall speed verdict is read from: the latency of a two-order decision (what the server does by
# default) and the batched throughput. The rest are reported but do not by themselves decide a record.
PRIMARY_METRICS = ("lat2_ms", "dec_s")


class MetricVerdict(Enum):
    BETTER = "BETTER"
    WORSE = "WORSE"
    SAME = "SAME"
    UNKNOWN = "UNKNOWN"  # a side is missing the metric, or the baseline is zero and no ratio exists


class Overall(Enum):
    BROKEN = "BROKEN"
    REGRESSION = "REGRESSION"
    MIXED = "MIXED"
    ANSWERS_CHANGED = "ANSWERS CHANGED"
    NO_CHANGE = "NO CHANGE"
    IMPROVEMENT = "IMPROVEMENT"
    IMPROVEMENT_WITH_CHANGED_ANSWERS = "IMPROVEMENT WITH CHANGED ANSWERS"


@dataclass(frozen=True)
class Gate:
    """A correctness condition. `blocking` gates make the record BROKEN; the others are recorded and shown."""
    name: str
    passed: bool
    detail: str
    blocking: bool = True


@dataclass(frozen=True)
class Comparison:
    """One metric of one (unit, mode), measured on both sides."""
    unit: str
    mode: str
    metric: str
    baseline: list[float]
    candidate: list[float]
    direction: Direction
    verdict: MetricVerdict
    baseline_median: float | None = None
    candidate_median: float | None = None
    relative_change: float | None = None   # signed, candidate against baseline
    improvement: float | None = None       # positive means better, whatever the direction
    noise_floor: float | None = None
    threshold: float | None = None

    def as_dict(self) -> dict:
        return {"unit": self.unit, "mode": self.mode, "metric": self.metric,
                "direction": self.direction.value, "verdict": self.verdict.value,
                "baseline": self.baseline, "candidate": self.candidate,
                "baseline_median": self.baseline_median, "candidate_median": self.candidate_median,
                "relative_change": self.relative_change, "improvement": self.improvement,
                "noise_floor": self.noise_floor, "threshold": self.threshold}


def noise_floor(values: list[float]) -> float:
    """Spread of one side's repeats, relative to its own median. One repeat has no measurable spread, hence 0.0."""
    usable = [v for v in values if v is not None]
    if len(usable) < 2:
        return 0.0
    median = statistics.median(usable)
    if median == 0:
        return 0.0
    return (max(usable) - min(usable)) / abs(median)


def classify(baseline: list[float], candidate: list[float], direction: Direction,
             min_relative_change: float = MIN_RELATIVE_CHANGE) -> dict:
    """Compare two sides of one metric. Returns the medians, the change, the threshold it had to beat, and a verdict."""
    base = [v for v in baseline if v is not None]
    cand = [v for v in candidate if v is not None]
    if not base or not cand:
        return {"verdict": MetricVerdict.UNKNOWN, "baseline_median": None, "candidate_median": None,
                "relative_change": None, "improvement": None, "noise_floor": None, "threshold": None}
    base_median, cand_median = statistics.median(base), statistics.median(cand)
    noise = max(noise_floor(base), noise_floor(cand))
    threshold = max(noise, min_relative_change)
    if base_median == 0:
        return {"verdict": MetricVerdict.UNKNOWN, "baseline_median": base_median,
                "candidate_median": cand_median, "relative_change": None, "improvement": None,
                "noise_floor": noise, "threshold": threshold}
    relative = (cand_median - base_median) / abs(base_median)
    improvement = -relative if direction is Direction.LOWER_BETTER else relative
    if improvement > threshold:
        verdict = MetricVerdict.BETTER
    elif improvement < -threshold:
        verdict = MetricVerdict.WORSE
    else:
        verdict = MetricVerdict.SAME
    return {"verdict": verdict, "baseline_median": base_median, "candidate_median": cand_median,
            "relative_change": relative, "improvement": improvement, "noise_floor": noise,
            "threshold": threshold}


def compare_series(series: dict[tuple[str, str, str], dict[str, list[float]]]) -> list[Comparison]:
    """series[(unit, mode, metric)] = {"baseline": [...], "candidate": [...]} -> one Comparison per timing metric."""
    out = []
    for (unit, mode, metric), sides in sorted(series.items()):
        direction = TIMING_METRICS.get(metric)
        if direction is None:
            continue  # not a timing metric: accuracy, memory and agreement go through the gates instead
        stats = classify(sides.get("baseline", []), sides.get("candidate", []), direction)
        out.append(Comparison(unit=unit, mode=mode, metric=metric, direction=direction,
                              baseline=sides.get("baseline", []), candidate=sides.get("candidate", []),
                              **stats))
    return out


def speed_verdict(comparisons: list[Comparison]) -> Overall:
    """The overall direction, read from the primary metrics only."""
    primary = [c for c in comparisons if c.metric in PRIMARY_METRICS]
    better = any(c.verdict is MetricVerdict.BETTER for c in primary)
    worse = any(c.verdict is MetricVerdict.WORSE for c in primary)
    if better and worse:
        return Overall.MIXED
    if better:
        return Overall.IMPROVEMENT
    if worse:
        return Overall.REGRESSION
    return Overall.NO_CHANGE


def memory_gate(series: dict[tuple[str, str, str], dict[str, list[float]]],
                tolerance: float = MEMORY_TOLERANCE) -> Gate:
    """Peak memory is near-deterministic, so it gets a flat tolerance instead of a noise floor."""
    worst, where = 0.0, None
    for (unit, mode, metric), sides in series.items():
        if metric != "mem_gb":
            continue
        stats = classify(sides.get("baseline", []), sides.get("candidate", []), Direction.LOWER_BETTER)
        growth = -(stats["improvement"] or 0.0)
        if growth > worst:
            worst, where = growth, f"{unit}/{mode}"
    if where is None:
        return Gate("memory", True, "no memory measurements (the backend does not report it)", blocking=False)
    passed = worst <= tolerance
    return Gate("memory", passed, f"worst peak-memory growth {worst:+.1%} at {where} "
                                  f"(tolerance {tolerance:.0%})")


def accuracy_gate(series: dict[tuple[str, str, str], dict[str, list[float]]]) -> Gate:
    """Accuracy must not fall further than the baseline's own repeat-to-repeat spread on the same items."""
    worst, where = 0.0, None
    for (unit, mode, metric), sides in series.items():
        if metric != "acc":
            continue
        base = [v for v in sides.get("baseline", []) if v is not None]
        cand = [v for v in sides.get("candidate", []) if v is not None]
        if not base or not cand:
            continue
        allowed = (max(base) - min(base)) if len(base) > 1 else 0.0
        drop = statistics.median(base) - statistics.median(cand)
        if drop - allowed > worst:
            worst, where = drop - allowed, f"{unit}/{mode}"
    if where is None:
        return Gate("accuracy", True, "no accuracy measurements (the items carry no gold labels)", blocking=False)
    return Gate("accuracy", worst <= 0.0,
                f"largest accuracy drop beyond the baseline's own spread: {worst:+.4f} at {where}")


def agreement_gate(agree_rows: list[dict], gate: float = AGREE_GATE) -> Gate:
    """basal-agree's own gate, applied to the candidate: a backend may not fall below it if the baseline passed."""
    if not agree_rows:
        return Gate("backend agreement", True, "basal-agree did not run in this profile", blocking=False)
    failures = [r for r in agree_rows if r.get("side") == "candidate" and r.get("gate_passed") is False]
    baseline_failures = {r.get("backend") for r in agree_rows
                         if r.get("side") == "baseline" and r.get("gate_passed") is False}
    new = [r for r in failures if r.get("backend") not in baseline_failures]
    if new:
        named = ", ".join(f"{r.get('backend')} {r.get('readouts_agreement')}" for r in new)
        return Gate("backend agreement", False, f"below {gate} on the candidate only: {named}")
    detail = f"every backend at or above {gate}" if not failures else \
        f"the same backends fail on both sides ({', '.join(sorted(baseline_failures))}): pre-existing"
    return Gate("backend agreement", True, detail)


def tests_gate(baseline: dict | None, candidate: dict | None) -> Gate:
