import statistics
from dataclasses import dataclass, field
from enum import Enum

from config import AGREE_GATE, MEMORY_TOLERANCE, MIN_RELATIVE_CHANGE, Direction, TIMING_METRICS

# Metrics the overall speed verdict is read from: the latency of a two-order decision (what the server does by
# default) and the batched throughput. The rest are reported but do not by themselves decide a record.
PRIMARY_METRICS = ("lat2_ms", "dec_s")


class MetricVerdict(Enum):
    BETTER = "BETTER"
    WORSE = "WORSE"
    SAME = "SAME"
    UNKNOWN = "UNKNOWN"  # a side is missing the metric, or the baseline is zero and no ratio exists


class Overall(Enum):
    BROKEN = "BROKEN"
    REGRESSION = "REGRESSION"
    MIXED = "MIXED"
    ANSWERS_CHANGED = "ANSWERS CHANGED"
    NO_CHANGE = "NO CHANGE"
    IMPROVEMENT = "IMPROVEMENT"
    IMPROVEMENT_WITH_CHANGED_ANSWERS = "IMPROVEMENT WITH CHANGED ANSWERS"


@dataclass(frozen=True)
class Gate:
    """A correctness condition. `blocking` gates make the record BROKEN; the others are recorded and shown."""
    name: str
    passed: bool
    detail: str
    blocking: bool = True


