class Comparison:
    """One metric of one (unit, mode), measured on both sides."""
    unit: str
    mode: str
    metric: str
    baseline: list[float]
    candidate: list[float]
    direction: Direction
    verdict: MetricVerdict
    baseline_median: float | None = None
    candidate_median: float | None = None
    relative_change: float | None = None   # signed, candidate against baseline
    improvement: float | None = None       # positive means better, whatever the direction
    noise_floor: float | None = None
    threshold: float | None = None

    def as_dict(self) -> dict:
        return {"unit": self.unit, "mode": self.mode, "metric": self.metric,
                "direction": self.direction.value, "verdict": self.verdict.value,
                "baseline": self.baseline, "candidate": self.candidate,
                "baseline_median": self.baseline_median, "candidate_median": self.candidate_median,
                "relative_change": self.relative_change, "improvement": self.improvement,
                "noise_floor": self.noise_floor, "threshold": self.threshold}


def noise_floor(values: list[float]) -> float:
    """Spread of one side's repeats, relative to its own median. One repeat has no measurable spread, hence 0.0."""
    usable = [v for v in values if v is not None]
    if len(usable) < 2:
        return 0.0
    median = statistics.median(usable)
    if median == 0:
        return 0.0
    return (max(usable) - min(usable)) / abs(median)


