             min_relative_change: float = MIN_RELATIVE_CHANGE) -> dict:
    """Compare two sides of one metric. Returns the medians, the change, the threshold it had to beat, and a verdict."""
    base = [v for v in baseline if v is not None]
    cand = [v for v in candidate if v is not None]
    if not base or not cand:
        return {"verdict": MetricVerdict.UNKNOWN, "baseline_median": None, "candidate_median": None,
                "relative_change": None, "improvement": None, "noise_floor": None, "threshold": None}
    base_median, cand_median = statistics.median(base), statistics.median(cand)
    noise = max(noise_floor(base), noise_floor(cand))
    threshold = max(noise, min_relative_change)
    if base_median == 0:
        return {"verdict": MetricVerdict.UNKNOWN, "baseline_median": base_median,
                "candidate_median": cand_median, "relative_change": None, "improvement": None,
                "noise_floor": noise, "threshold": threshold}
    relative = (cand_median - base_median) / abs(base_median)
    improvement = -relative if direction is Direction.LOWER_BETTER else relative
    if improvement > threshold:
        verdict = MetricVerdict.BETTER
    elif improvement < -threshold:
        verdict = MetricVerdict.WORSE
    else:
        verdict = MetricVerdict.SAME
    return {"verdict": verdict, "baseline_median": base_median, "candidate_median": cand_median,
            "relative_change": relative, "improvement": improvement, "noise_floor": noise,
            "threshold": threshold}


