    better = any(c.verdict is MetricVerdict.BETTER for c in primary)
    worse = any(c.verdict is MetricVerdict.WORSE for c in primary)
    if better and worse:
        return Overall.MIXED
    if better:
        return Overall.IMPROVEMENT
    if worse:
        return Overall.REGRESSION
    return Overall.NO_CHANGE


def memory_gate(series: dict[tuple[str, str, str], dict[str, list[float]]],
                tolerance: float = MEMORY_TOLERANCE) -> Gate:
    """Peak memory is near-deterministic, so it gets a flat tolerance instead of a noise floor."""
    worst, where = 0.0, None
    for (unit, mode, metric), sides in series.items():
        if metric != "mem_gb":
            continue
        stats = classify(sides.get("baseline", []), sides.get("candidate", []), Direction.LOWER_BETTER)
        growth = -(stats["improvement"] or 0.0)
        if growth > worst:
            worst, where = growth, f"{unit}/{mode}"
    if where is None:
        return Gate("memory", True, "no memory measurements (the backend does not report it)", blocking=False)
    passed = worst <= tolerance
    return Gate("memory", passed, f"worst peak-memory growth {worst:+.1%} at {where} "
