                f"largest accuracy drop beyond the baseline's own spread: {worst:+.4f} at {where}")


def agreement_gate(agree_rows: list[dict], gate: float = AGREE_GATE) -> Gate:
    """basal-agree's own gate, applied to the candidate: a backend may not fall below it if the baseline passed."""
    if not agree_rows:
        return Gate("backend agreement", True, "basal-agree did not run in this profile", blocking=False)
    failures = [r for r in agree_rows if r.get("side") == "candidate" and r.get("gate_passed") is False]
    baseline_failures = {r.get("backend") for r in agree_rows
                         if r.get("side") == "baseline" and r.get("gate_passed") is False}
    new = [r for r in failures if r.get("backend") not in baseline_failures]
    if new:
        named = ", ".join(f"{r.get('backend')} {r.get('readouts_agreement')}" for r in new)
        return Gate("backend agreement", False, f"below {gate} on the candidate only: {named}")
    detail = f"every backend at or above {gate}" if not failures else \
        f"the same backends fail on both sides ({', '.join(sorted(baseline_failures))}): pre-existing"
    return Gate("backend agreement", True, detail)


def tests_gate(baseline: dict | None, candidate: dict | None) -> Gate:
    """A test that fails only on the candidate. A failure present on both sides is pre-existing, not this change."""
    if not baseline or not candidate:
        return Gate("tests", True, "pytest did not run in this profile", blocking=False)
    new = sorted(set(candidate.get("failed_tests", [])) - set(baseline.get("failed_tests", [])))
    if new:
        return Gate("tests", False, f"{len(new)} test(s) fail only on the candidate: {', '.join(new[:5])}")
    pre_existing = sorted(set(baseline.get("failed_tests", [])))
    detail = "no new failures" + (f"; {len(pre_existing)} pre-existing on both sides" if pre_existing else "")
    return Gate("tests", True, detail)


def determinism_gate(rows: list[dict]) -> Gate:
    """If a side's server is not reproducible under load, its answer diff cannot be attributed to the code."""
    if not rows:
        return Gate("determinism", True, "the determinism probe did not run in this profile", blocking=False)
    bad = [r for r in rows if r.get("decision_flips", 0) or r.get("load_errors", 0)
           or r.get("identical", 0) != r.get("requests", 0)]
    if bad:
        worst = max(bad, key=lambda r: r.get("max_abs_diff", 0))
        return Gate("determinism", False,
                    f"{len(bad)} probe(s) not reproducible under load; worst max|dp| {worst.get('max_abs_diff')}, "
                    f"flips {worst.get('decision_flips')}, errors {worst.get('load_errors')}")
    return Gate("determinism", True, "every probe returned identical answers alone and under load")


def errors_gate(loadtest_rows: list[dict]) -> Gate:
    failing = [r for r in loadtest_rows if r.get("errors")]
    if not loadtest_rows:
        return Gate("http errors", True, "the load test did not run in this profile", blocking=False)
    if failing:
        total = sum(r.get("errors", 0) for r in failing)
        return Gate("http errors", False, f"{total} failed request(s) across {len(failing)} load test(s)")
    return Gate("http errors", True, "no failed requests")


def answers_gate(answer_diffs: list[dict]) -> Gate:
    """Not blocking: a changed answer is reported as its own verdict, not treated as a broken build."""
    if not answer_diffs:
        return Gate("answers", True, "the answer diff did not run", blocking=False)
    changed = [d for d in answer_diffs if d.get("verdict") == "CHANGED"]
    if changed:
        worst = max(changed, key=lambda d: d["overall"]["max_abs_dp"])
        real_flips = worst["overall"]["flips"] - worst["overall"]["near_tie_flips"]
        return Gate("answers", False,
                    f"{len(changed)} of {len(answer_diffs)} comparison(s) CHANGED; worst: {real_flips} decision "
                    f"flip(s) beyond near ties, max|dp| {worst['overall']['max_abs_dp']:.4f}", blocking=False)
    verdicts = sorted({d.get("verdict") for d in answer_diffs})
    return Gate("answers", True, f"served answers {' and '.join(verdicts)} on every compared mode", blocking=False)


@dataclass
class Assessment:
    overall: Overall
    speed: Overall
    gates: list[Gate] = field(default_factory=list)
    comparisons: list[Comparison] = field(default_factory=list)

    @property
    def blocking_failures(self) -> list[Gate]:
        return [g for g in self.gates if g.blocking and not g.passed]

    def as_dict(self) -> dict:
        return {"overall": self.overall.value, "speed": self.speed.value,
                "gates": [{"name": g.name, "passed": g.passed, "blocking": g.blocking, "detail": g.detail}
                          for g in self.gates],
                "comparisons": [c.as_dict() for c in self.comparisons]}


def assess(comparisons: list[Comparison], gates: list[Gate], answers_changed: bool) -> Assessment:
    """Correctness first, then speed. A changed answer never silently reads as a free win."""
    speed = speed_verdict(comparisons)
    blocking = [g for g in gates if g.blocking and not g.passed]
    if blocking:
        overall = Overall.BROKEN
    elif answers_changed:
        overall = {Overall.IMPROVEMENT: Overall.IMPROVEMENT_WITH_CHANGED_ANSWERS,
                   Overall.REGRESSION: Overall.REGRESSION,
                   Overall.MIXED: Overall.MIXED}.get(speed, Overall.ANSWERS_CHANGED)
    else:
        overall = speed
    return Assessment(overall=overall, speed=speed, gates=gates, comparisons=comparisons)

