"""Tests for the verdict rules. A fault here would state improvements that never happened.

  cd harness && python -m pytest test_verdict.py -q
"""
from config import Direction
from verdict import (Gate, MetricVerdict, Overall, assess, accuracy_gate, classify, compare_series,
                     memory_gate, noise_floor, speed_verdict, tests_gate)


def latency(values):
    return classify(values["baseline"], values["candidate"], Direction.LOWER_BETTER)


# --- the noise floor ------------------------------------------------------------------------------------------

def test_given_one_repeat_when_noise_floor_computed_then_it_is_zero():
    """One measurement has no measurable spread; the flat minimum threshold is what protects such a run."""
    assert noise_floor([100.0]) == 0.0


def test_given_repeats_when_noise_floor_computed_then_it_is_the_spread_over_the_median():
    assert noise_floor([90.0, 100.0, 110.0]) == 0.2


# --- classification -------------------------------------------------------------------------------------------

def test_given_a_large_latency_drop_when_classified_then_better():
    result = latency({"baseline": [100.0, 101.0, 99.0], "candidate": [80.0, 81.0, 79.0]})
    assert result["verdict"] is MetricVerdict.BETTER
    assert result["improvement"] > 0


def test_given_a_large_latency_rise_when_classified_then_worse():
    result = latency({"baseline": [80.0, 81.0, 79.0], "candidate": [100.0, 101.0, 99.0]})
    assert result["verdict"] is MetricVerdict.WORSE
    assert result["improvement"] < 0


def test_given_a_change_smaller_than_the_minimum_when_classified_then_same():
    """Tight repeats give a noise floor near zero, so the flat 3% minimum must still suppress a 1% move."""
    result = latency({"baseline": [100.0, 100.0, 100.0], "candidate": [99.0, 99.0, 99.0]})
    assert result["noise_floor"] == 0.0
    assert result["threshold"] == 0.03
    assert result["verdict"] is MetricVerdict.SAME


def test_given_a_change_within_a_noisy_runs_spread_when_classified_then_same():
    """The run wobbled by 30%; an 8% apparent gain is not distinguishable from that drift."""
    result = latency({"baseline": [85.0, 100.0, 115.0], "candidate": [78.0, 92.0, 106.0]})
    assert result["noise_floor"] > 0.08
    assert result["verdict"] is MetricVerdict.SAME


def test_given_higher_is_better_when_throughput_rises_then_better():
    result = classify([10.0, 10.0], [20.0, 20.0], Direction.HIGHER_BETTER)
    assert result["verdict"] is MetricVerdict.BETTER


def test_given_higher_is_better_when_throughput_falls_then_worse():
    result = classify([20.0, 20.0], [10.0, 10.0], Direction.HIGHER_BETTER)
    assert result["verdict"] is MetricVerdict.WORSE


def test_given_a_missing_side_when_classified_then_unknown_not_same():
    """A mode that failed to run must never be reported as unchanged."""
    assert classify([], [100.0], Direction.LOWER_BETTER)["verdict"] is MetricVerdict.UNKNOWN


def test_given_a_zero_baseline_when_classified_then_unknown():
    assert classify([0.0], [5.0], Direction.LOWER_BETTER)["verdict"] is MetricVerdict.UNKNOWN


# --- aggregation ----------------------------------------------------------------------------------------------

def series(metric, baseline, candidate, unit="mini-bf16", mode="mps"):
    return {(unit, mode, metric): {"baseline": baseline, "candidate": candidate}}


def test_given_a_non_timing_metric_when_series_compared_then_it_is_skipped():
    """Accuracy and memory go through gates, not the noise-floor path."""
    assert compare_series(series("acc", [0.9], [0.9])) == []


def test_given_mixed_primary_metrics_when_speed_judged_then_mixed():
    comparisons = compare_series({**series("lat2_ms", [100.0], [50.0]),
                                  **series("dec_s", [10.0], [5.0])})
    assert speed_verdict(comparisons) is Overall.MIXED


def test_given_only_secondary_metrics_moved_when_speed_judged_then_no_change():
    """load_s is reported but must not by itself declare a record an improvement."""
    comparisons = compare_series(series("load_s", [100.0], [10.0]))
    assert speed_verdict(comparisons) is Overall.NO_CHANGE


# --- gates ----------------------------------------------------------------------------------------------------

def test_given_memory_growth_beyond_tolerance_when_gated_then_it_fails():
    gate = memory_gate(series("mem_gb", [4.0], [5.0]))
    assert not gate.passed and gate.blocking


def test_given_memory_growth_within_tolerance_when_gated_then_it_passes():
    assert memory_gate(series("mem_gb", [4.0], [4.2])).passed


def test_given_no_memory_measurements_when_gated_then_it_is_non_blocking():
    """GGUF and CPU backends report no memory; that is a gap in the data, not a failure."""
    gate = memory_gate({})
    assert gate.passed and not gate.blocking


def test_given_an_accuracy_drop_beyond_the_baseline_spread_when_gated_then_it_fails():
    gate = accuracy_gate(series("acc", [0.900, 0.900, 0.900], [0.850, 0.850, 0.850]))
    assert not gate.passed


def test_given_an_accuracy_drop_within_the_baseline_spread_when_gated_then_it_passes():
    """The baseline itself wandered by 0.05 between repeats, so a 0.02 drop says nothing."""
    assert accuracy_gate(series("acc", [0.88, 0.90, 0.93], [0.88, 0.88, 0.88])).passed


def test_given_a_test_failing_only_on_the_candidate_when_gated_then_it_fails():
    gate = tests_gate({"failed_tests": []}, {"failed_tests": ["tests/test_engine.py::test_x"]})
    assert not gate.passed


def test_given_a_test_failing_on_both_sides_when_gated_then_it_passes_as_pre_existing():
    failing = {"failed_tests": ["tests/test_engine.py::test_x"]}
    gate = tests_gate(failing, failing)
    assert gate.passed and "pre-existing" in gate.detail


# --- the overall verdict --------------------------------------------------------------------------------------

FASTER = compare_series(series("lat2_ms", [100.0, 100.0], [70.0, 70.0]))
SLOWER = compare_series(series("lat2_ms", [70.0, 70.0], [100.0, 100.0]))
UNCHANGED = compare_series(series("lat2_ms", [100.0, 100.0], [100.0, 100.0]))
PASSING = [Gate("tests", True, "ok")]
FAILING = [Gate("tests", False, "a new failure")]


def test_given_a_blocking_gate_failure_when_assessed_then_broken_however_fast():
    assert assess(FASTER, FAILING, answers_changed=False).overall is Overall.BROKEN


def test_given_faster_and_unchanged_answers_when_assessed_then_improvement():
    assert assess(FASTER, PASSING, answers_changed=False).overall is Overall.IMPROVEMENT


def test_given_faster_but_changed_answers_when_assessed_then_the_win_is_qualified():
    """A speed win bought with different answers must never read as a free win."""
    assert assess(FASTER, PASSING, answers_changed=True).overall is \
        Overall.IMPROVEMENT_WITH_CHANGED_ANSWERS


def test_given_changed_answers_and_no_speed_change_when_assessed_then_answers_changed():
    assert assess(UNCHANGED, PASSING, answers_changed=True).overall is Overall.ANSWERS_CHANGED


def test_given_slower_when_assessed_then_regression():
    assert assess(SLOWER, PASSING, answers_changed=False).overall is Overall.REGRESSION


def test_given_nothing_moved_when_assessed_then_no_change():
    assert assess(UNCHANGED, PASSING, answers_changed=False).overall is Overall.NO_CHANGE


def test_given_a_non_blocking_gate_failure_when_assessed_then_it_does_not_break_the_record():
    gates = [Gate("answers", False, "CHANGED", blocking=False)]
    assert assess(FASTER, gates, answers_changed=True).overall is Overall.IMPROVEMENT_WITH_CHANGED_ANSWERS

