    return out


PYTEST_SUMMARY = re.compile(r"(?P<count>\d+) (?P<kind>passed|failed|skipped|error|errors|xfailed|xpassed)")
PYTEST_FAILURE = re.compile(r"^(?P<test>\S+::\S+)\s", re.MULTILINE)


def parse_pytest(log: Path) -> dict | None:
    """Counts and the names of failing tests, from pytest's own terse output."""
    if not log.exists():
        return None
    text = log.read_text(encoding="utf-8", errors="replace")
    counts = {}
    for match in PYTEST_SUMMARY.finditer(text):
        kind = match.group("kind").rstrip("s") if match.group("kind").startswith("error") else match.group("kind")
        counts[kind] = max(counts.get(kind, 0), int(match.group("count")))
    failed = sorted({m.group("test") for m in PYTEST_FAILURE.finditer(text)
                     if "FAILED" in text[max(0, m.start() - 80):m.end() + 80]
                     or text[m.start():m.end()].startswith("FAILED")})
    explicit = sorted({line.split(" ")[1] for line in text.splitlines()
                       if line.startswith("FAILED ") and len(line.split(" ")) > 1})
    return {"counts": counts, "failed_tests": explicit or failed, "log": str(log)}

