"""Tests for reading each tool's own JSON. The shapes here are copied from the basal CLIs that produce them.

  cd harness && python -m pytest test_metrics.py -q
"""
from config import Side
from metrics import (Series, absorb_bench, absorb_loadtest, agree_rows, determinism_rows, loadtest_rows,
                     mode_key, parse_pytest)


def bench_row(mode, lat2, dec_s=7.0, acc=0.705, mem=4.1):
    """The shape basal-bench --out writes, one object per mode."""
    return {"mode": mode, "reference_mode": "mps", "gpu": "Apple M4", "n": 44, "load_s": 12.3,
            "lat1_ms": lat2 / 2, "lat2_ms": lat2, "lat2_p95_ms": lat2 * 1.2, "dec_s": dec_s,
            "mem_gb": mem, "acc": acc, "agree": 1.0}


def test_given_a_gguf_mode_with_a_cache_path_when_keyed_then_the_path_is_dropped():
    """The path is this machine's, not the comparison's, so both sides must land on the same key."""
    assert mode_key("gguf@/Volumes/drive/x/basal-2.0-mini-Q8_0.gguf") == "gguf"


def test_given_a_plain_mode_when_keyed_then_it_is_unchanged():
    assert mode_key("mlx-q8") == "mlx-q8"


def test_given_bench_output_for_both_sides_when_absorbed_then_the_series_pairs_them():
    series = Series()
    absorb_bench(series, "mini-bf16", Side.BASELINE, [bench_row("mps", 141.2)])
    absorb_bench(series, "mini-bf16", Side.CANDIDATE, [bench_row("mps", 120.0)])
    assert series.as_dict()[("mini-bf16", "mps", "lat2_ms")] == {"baseline": [141.2], "candidate": [120.0]}


def test_given_repeated_bench_runs_when_absorbed_then_values_accumulate_in_order():
    series = Series()
    for lat in (141.2, 139.0, 150.0):
        absorb_bench(series, "mini-bf16", Side.BASELINE, [bench_row("mps", lat)])
    assert series.as_dict()[("mini-bf16", "mps", "lat2_ms")]["baseline"] == [141.2, 139.0, 150.0]


def test_given_a_null_memory_reading_when_absorbed_then_it_is_omitted_not_zero():
    """basal-bench writes null for backends it cannot measure (GGUF, CPU); zero would read as a memory win."""
    series = Series()
    row = bench_row("gguf@/x.gguf", 133.1)
    row["mem_gb"] = None
    absorb_bench(series, "mini-bf16", Side.BASELINE, [row])
    assert ("mini-bf16", "gguf", "mem_gb") not in series.as_dict()
    assert ("mini-bf16", "gguf", "lat2_ms") in series.as_dict()


def test_given_malformed_bench_output_when_absorbed_then_nothing_is_invented():
    series = Series()
    absorb_bench(series, "mini-bf16", Side.BASELINE, None)
    absorb_bench(series, "mini-bf16", Side.BASELINE, [{"no_mode": 1}])
    assert series.as_dict() == {}


def test_given_loadtest_output_when_absorbed_then_its_metrics_are_kept():
    series = Series()
    payload = {"url": "http://127.0.0.1:8000/v1/systemone", "p50_ms": 141.0, "p95_ms": 160.0,
               "concurrency": 32, "decisions_per_s": 7.1, "errors": 0}
    absorb_loadtest(series, "mini-bf16", "mps", Side.BASELINE, payload)
    assert series.as_dict()[("mini-bf16", "mps", "p50_ms")]["baseline"] == [141.0]
    assert series.as_dict()[("mini-bf16", "mps", "errors")]["baseline"] == [0.0]


def test_given_a_determinism_payload_when_absorbed_as_a_loadtest_then_it_is_ignored():
    """The two forms share a --out file shape; mixing them would pollute the latency series."""
    series = Series()
    absorb_loadtest(series, "mini-bf16", "mps", Side.BASELINE,
                    {"url": "u", "determinism": {"requests": 100, "identical": 100}})
    assert series.as_dict() == {}


def test_given_a_determinism_payload_when_rows_extracted_then_the_probe_is_flattened():
    payload = {"url": "u", "determinism": {"requests": 100, "identical": 100, "max_abs_diff": 0.0,
                                           "decision_flips": 0, "concurrency": 32, "load_errors": 0}}
    rows = determinism_rows([("mini-bf16", "mps", Side.BASELINE, payload)])
    assert rows == [{"unit": "mini-bf16", "mode": "mps", "side": "baseline", "requests": 100, "identical": 100,
                     "max_abs_diff": 0.0, "decision_flips": 0, "concurrency": 32, "load_errors": 0}]


def test_given_both_loadtest_forms_when_rows_extracted_then_only_the_latency_one_is_returned():
    plain = {"url": "u", "p50_ms": 1.0, "errors": 0}
    probe = {"url": "u", "determinism": {"requests": 10}}
    rows = loadtest_rows([("mini-bf16", "mps", Side.BASELINE, plain),
                          ("mini-bf16", "mps", Side.BASELINE, probe)])
    assert len(rows) == 1 and rows[0]["p50_ms"] == 1.0


def test_given_agree_output_when_rows_extracted_then_the_pass_string_becomes_a_boolean():
    """basal-agree writes gate as "pass"/"fail"; the gate logic must not depend on that spelling."""
    payload = {"model": "Remek/basal-2.0-mini", "reference": "eager-fp32", "version": "2.8.1", "rows": [
        {"backend": "mps", "agreement": 1.0, "near_ties": 0, "readouts": 240, "gate": "pass"},
        {"backend": "mlx", "agreement": 0.97, "near_ties": 1, "readouts": 240, "gate": "fail"}]}
    rows = agree_rows([("mini-bf16", Side.CANDIDATE, payload)])
    assert [r["gate_passed"] for r in rows] == [True, False]
    assert rows[0]["reference"] == "eager-fp32"


def test_given_an_agree_backend_named_with_weights_when_extracted_then_it_keys_on_the_mode():
    payload = {"rows": [{"backend": "mlx=Remek/basal-2.0-mini-MLX-8bit", "gate": "pass"}]}
    assert agree_rows([("mini-mlx8", Side.BASELINE, payload)])[0]["backend"] == "mlx"


def test_given_a_pytest_log_with_failures_when_parsed_then_the_names_are_recovered(tmp_path):
    log = tmp_path / "pytest.txt"
    log.write_text("..F..\n"
                   "FAILED tests/test_engine.py::test_prefix - AssertionError: 3 != 4\n"
                   "ERROR tests/test_media.py::test_audio\n"
                   "1 failed, 4 passed, 2 skipped in 3.21s\n", encoding="utf-8")
    parsed = parse_pytest(log)
    assert parsed["failed_tests"] == ["tests/test_engine.py::test_prefix", "tests/test_media.py::test_audio"]
    assert parsed["counts"] == {"failed": 1, "passed": 4, "skipped": 2}


def test_given_a_clean_pytest_log_when_parsed_then_no_failures_are_reported(tmp_path):
    log = tmp_path / "pytest.txt"
    log.write_text("1840 passed, 96 skipped in 412.30s\n", encoding="utf-8")
    parsed = parse_pytest(log)
    assert parsed["failed_tests"] == []
    assert parsed["counts"]["passed"] == 1840


def test_given_no_pytest_log_when_parsed_then_none_so_the_gate_stays_non_blocking(tmp_path):
    assert parse_pytest(tmp_path / "absent.txt") is None

