"""Reading each tool's own JSON into one shape, without reinterpreting any number it reported.

Every basal CLI writes its own `--out` structure. This module flattens those into

    series[(unit, mode, metric)] = {"baseline": [v, ...], "candidate": [v, ...]}

one value per repeat, in repeat order, which is what verdict.py compares. Raw files are kept verbatim in the
record's raw/ directory; nothing here rounds, rescales or infers a missing value.
"""
import json
import re
from pathlib import Path

from config import Side

# basal-bench echoes a gguf mode back as `gguf@/long/cache/path.gguf`. The path is a property of this machine, not
# of the comparison, so the key collapses to `gguf` and the resolved path is recorded in meta.json instead.
MODE_KEY = re.compile(r"^(?P<mode>[a-z0-9-]+)(@.*)?$")

BENCH_METRICS = ("lat1_ms", "lat2_ms", "lat2_p95_ms", "dec_s", "load_s", "mem_gb", "acc", "agree")
LOADTEST_METRICS = ("p50_ms", "p95_ms", "decisions_per_s", "questions_per_s", "errors")


def mode_key(mode: str) -> str:
    match = MODE_KEY.match(mode)
    return match.group("mode") if match else mode


def read_json(path: Path) -> object | None:
    """A phase that did not run, or crashed before writing, leaves no file. That is recorded, never guessed at."""
    if not path.exists():
        return None
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except ValueError:
        return None


class Series:
    """Accumulates one value per (unit, mode, metric, side), in the order repeats were run."""

    def __init__(self) -> None:
        self._data: dict[tuple[str, str, str], dict[str, list[float]]] = {}

    def add(self, unit: str, mode: str, metric: str, side: Side, value) -> None:
        if value is None or isinstance(value, bool):
            return
        if not isinstance(value, (int, float)):
            return
        key = (unit, mode_key(mode), metric)
        self._data.setdefault(key, {"baseline": [], "candidate": []})[side.value].append(float(value))

    def as_dict(self) -> dict[tuple[str, str, str], dict[str, list[float]]]:
        return self._data

    def jsonable(self) -> dict:
        """The same data with string keys, for record.json."""
        return {f"{unit}|{mode}|{metric}": sides for (unit, mode, metric), sides in sorted(self._data.items())}


def absorb_bench(series: Series, unit: str, side: Side, payload) -> None:
    """basal-bench --out: a list of one row per mode."""
    if not isinstance(payload, list):
        return
    for row in payload:
        if not isinstance(row, dict) or "mode" not in row:
            continue
        for metric in BENCH_METRICS:
            series.add(unit, row["mode"], metric, side, row.get(metric))


def absorb_loadtest(series: Series, unit: str, mode: str, side: Side, payload) -> None:
    """basal-loadtest --out: one object. The determinism form is handled separately."""
    if not isinstance(payload, dict) or "determinism" in payload:
        return
    for metric in LOADTEST_METRICS:
        series.add(unit, mode, metric, side, payload.get(metric))


def determinism_rows(payloads: list[tuple[str, str, Side, object]]) -> list[dict]:
    """The determinism probes, tagged with where each came from, for verdict.determinism_gate."""
    rows = []
    for unit, mode, side, payload in payloads:
        if not isinstance(payload, dict):
            continue
        probe = payload.get("determinism")
        if isinstance(probe, dict):
            rows.append({"unit": unit, "mode": mode_key(mode), "side": side.value, **probe})
    return rows


def loadtest_rows(payloads: list[tuple[str, str, Side, object]]) -> list[dict]:
    rows = []
    for unit, mode, side, payload in payloads:
        if isinstance(payload, dict) and "determinism" not in payload:
            rows.append({"unit": unit, "mode": mode_key(mode), "side": side.value, **payload})
    return rows


def agree_rows(payloads: list[tuple[str, Side, object]]) -> list[dict]:
    """basal-agree --out: {model, revision, reference, version, questions, rows:[...]}.

    `gate` is the string "pass"/"fail"; it becomes `gate_passed` so the gate logic does not depend on that spelling.
    """
    out = []
    for unit, side, payload in payloads:
        if not isinstance(payload, dict):
            continue
        for row in payload.get("rows", []):
            if not isinstance(row, dict):
                continue
            out.append({"unit": unit, "side": side.value, "reference": payload.get("reference"),
                        "backend": mode_key(str(row.get("backend", ""))),
                        "gate_passed": row.get("gate") == "pass",
                        "readouts_agreement": row.get("agreement"),
                        "agreement_ci": row.get("agreement_ci"),
                        "near_ties": row.get("near_ties"), "readouts": row.get("readouts"),
                        "mean_dp": row.get("mean_dp"), "max_dp": row.get("max_dp"),
                        "decision_agreement": row.get("decision_agreement"),
                        "accuracy": row.get("accuracy"), "reference_accuracy": row.get("reference_accuracy"),
                        "accuracy_diff_ci": row.get("accuracy_diff_ci"),
                        "independence": row.get("independence"),
                        "independence_max_dp": row.get("independence_max_dp"),
                        "load_s": row.get("load_s"), "run_s": row.get("run_s")})
    return out


def order_rows(payloads: list[tuple[str, str, Side, object]]) -> list[dict]:
    """basal-bench --order-check --out: kept whole, since its keys depend on the --average values requested."""
    out = []
    for unit, mode, side, payload in payloads:
        if payload is None:
            continue
        rows = payload if isinstance(payload, list) else [payload]
        for row in rows:
            if isinstance(row, dict):
                out.append({"unit": unit, "mode": mode_key(mode), "side": side.value, **row})
    return out


PYTEST_SUMMARY = re.compile(r"(?P<count>\d+) (?P<kind>passed|failed|skipped|error|errors|xfailed|xpassed)")
# pytest's short summary, which `-q` still prints: "FAILED tests/test_x.py::test_y - AssertionError: ..."
PYTEST_OUTCOME = re.compile(r"^(?P<outcome>FAILED|ERROR) (?P<test>\S+)", re.MULTILINE)


def parse_pytest(log: Path) -> dict | None:
    """Counts and the names of failing tests, from pytest's own short summary."""
    if not log.exists():
        return None
    text = log.read_text(encoding="utf-8", errors="replace")
    counts = {}
    for match in PYTEST_SUMMARY.finditer(text):
        kind = "error" if match.group("kind").startswith("error") else match.group("kind")
        counts[kind] = max(counts.get(kind, 0), int(match.group("count")))
    failed = sorted({m.group("test") for m in PYTEST_OUTCOME.finditer(text)})
    return {"counts": counts, "failed_tests": failed, "log": str(log)}

"""The commands each phase runs. Pure: these build argument lists, they never execute anything.

Every phase is an existing basal CLI, invoked as `python -m basal.<module>` from inside a worktree so that the
worktree's own `basal/` package shadows the copy in site-packages. Never the console scripts (`basal-bench`,
`basal-serve`): those resolve to the installed copy and would silently measure the wrong commit.
"""
from pathlib import Path

from config import Unit

QUESTIONS = Path("questions/bench_items.jsonl")  # relative to the harness directory; resolved by the caller


def _mode_args(unit: Unit, modes: tuple[str, ...], gguf_path: Path | None) -> list[str]:
    """`gguf` becomes `gguf@<file>` so one bench run can cover it beside the PyTorch and MLX modes."""
    out = []
    for m in modes:
        if m == "gguf":
            if gguf_path is None:
                continue  # the unit declares no GGUF file, or it is not downloaded: the mode is skipped, not faked
            out.append(f"gguf@{gguf_path}")
        else:
            out.append(m)
    return out


def bench(python: str, unit: Unit, modes: tuple[str, ...], questions: Path, n: int, lat_n: int,
          out: Path, gguf_path: Path | None = None) -> list[str]:
    """Offline latency, throughput, memory, accuracy and in-run agreement across modes."""
    return [python, "-m", "basal.bench", "--model", unit.model,
            "--modes", *_mode_args(unit, modes, gguf_path),
            "--questions", str(questions), "--n", str(n), "--lat-n", str(lat_n), "--out", str(out)]


def order_check(python: str, unit: Unit, mode: str, questions: Path, n: int, out: Path,
                gguf_path: Path | None = None) -> list[str]:
    """Option-order sensitivity: how often the top pick flips, and what averaging over K orders buys."""
    resolved = _mode_args(unit, (mode,), gguf_path)
    return [python, "-m", "basal.bench", "--order-check", "--model", unit.model, "--mode", resolved[0],
            "--questions", str(questions), "--n", str(n), "--out", str(out)]


def agree(python: str, unit: Unit, backends: tuple[str, ...], reference: str, questions: Path, out: Path,
          gguf_path: Path | None = None) -> list[str]:
    """Every backend against the native engine, with bootstrap intervals and question independence."""
    return [python, "-m", "basal.agree", "--model", unit.model,
            "--backends", *_mode_args(unit, backends, gguf_path),
            "--reference", reference, "--questions", str(questions), "--out", str(out)]


def serve(python: str, unit: Unit, mode: str, port: int, gguf_path: Path | None = None) -> list[str]:
    """A deterministic server, so a probability that moves between commits is the code change and not batch shape."""
    argv = [python, "-m", "basal.server", "--model", unit.model, "--mode", mode,
            "--host", "127.0.0.1", "--port", str(port), "--deterministic"]
    if mode == "gguf":
        if gguf_path is None:
            raise ValueError("mode gguf needs a resolved GGUF file")
        argv += ["--gguf", str(gguf_path)]
    return argv


def answers(python: str, url: str, questions: Path, out: Path) -> list[str]:
    """One answer per item, one request at a time: the input to the cross-commit answer diff."""
    return [python, "-m", "basal.run", "--url", url, "--input", str(questions), "--output", str(out),
            "--concurrency", "1", "--restart"]


def loadtest(python: str, url: str, questions: Path, out: Path, n_seq: int, n_conc: int, concurrency: int,
             questions_per_request: int = 1) -> list[str]:
    argv = [python, "-m", "basal.loadtest", "--url", url, "--questions", str(questions),
            "--n-seq", str(n_seq), "--n-conc", str(n_conc), "--concurrency", str(concurrency), "--out", str(out)]
    if questions_per_request > 1:
        argv += ["--questions-per-request", str(questions_per_request)]
    return argv


def determinism(python: str, url: str, questions: Path, out: Path, n: int, concurrency: int) -> list[str]:
    """The same requests alone and under load: a server that is not reproducible invalidates the answer diff."""
    return [python, "-m", "basal.loadtest", "--url", url, "--questions", str(questions),
            "--determinism", str(n), "--concurrency", str(concurrency), "--out", str(out)]


def tests(python: str) -> list[str]:
    return [python, "-m", "pytest", "-q", "-p", "no:cacheprovider", "-n", "auto"]

