"""Tests for the unit and profile matrix: which modes run, and what each phase measures against.

A reference mode that the profile never ran, or an agree run against weights the reference engine cannot read,
produces a phase whose numbers mean nothing. These check that cannot happen.

  cd harness && python -m pytest test_config.py -q
"""
from config import PROFILES, UNITS


def test_given_the_quick_profile_when_modes_resolved_then_only_the_filtered_ones_run():
    profile, unit = PROFILES["quick"], UNITS["mini-bf16"]
    assert profile.modes_for(unit) == ("mps", "mlx")


def test_given_a_filtered_profile_when_the_bench_reference_is_chosen_then_it_is_a_mode_that_runs():
    """basal-bench uses its first --modes entry as the reference; naming a filtered-out mode would be meaningless."""
    profile, unit = PROFILES["quick"], UNITS["mini-bf16"]
    reference = profile.bench_reference_for(unit)
    assert reference == "mps"
    assert reference in profile.modes_for(unit)


def test_given_an_unfiltered_profile_when_the_bench_reference_is_chosen_then_it_is_the_units_first_mode():
    profile, unit = PROFILES["thorough"], UNITS["mini-bf16"]
    assert profile.bench_reference_for(unit) == "eager-fp32"


def test_given_the_4_5b_unit_then_it_declares_no_fp32_reference():
    """fp32 4.5B is about 18 GB and this machine has 16 GB, so bf16 mps is the reference instead."""
    unit = UNITS["4.5B-bf16"]
    assert "eager-fp32" not in unit.modes
    assert unit.agree_reference == "mps"


def test_given_the_mini_unit_then_it_keeps_a_true_fp32_reference():
    assert UNITS["mini-bf16"].agree_reference == "eager-fp32"


