@staticmethod
def _status(result) -> str:
    """A phase is `ok` only when every command inside it succeeded.

    `fn` may return one Result or a list of them; a phase that runs several commands (the served phases) must
    not report `ok` because its own wrapper returned cleanly while a command inside it failed.
    """
    results = result if isinstance(result, list) else [result]
    failed = [r for r in results if r is not None and not getattr(r, "ok", True)]
    if failed:
        return "; ".join(f"{Path(r.log).name} exit {r.returncode}" for r in failed)
    return "ok"

def timed(self, name: str, fn):
    started = time.monotonic()
    try:
        result = fn()
        status = self._status(result)
    except Exception as e:                                    # a phase must not abort the whole record
        result, status = None, f"{type(e).__name__}: {e}"
    self.phases.append({"name": name, "seconds": time.monotonic() - started, "status": status})
    return result

