toolUseResult.originalFile:
"""Cross-commit answer equality: did the candidate change what the engine decides?

`basal-bench`'s `agree` column compares modes *inside one run*, so it cannot answer this. This does: it diffs two
`basal-run` output files produced from the same input against two deterministic servers, one per commit.

  python harness/compare_answers.py baseline.jsonl candidate.jsonl --out answers_diff.json

Reported:
  lines                  items compared (and any that only one side answered)
  identical              items whose every probability matched to the bit
  decision_flips         items where the chosen option changed  <- the one that matters
  max_abs_dp / p99_abs_dp  largest and 99th-percentile change of any single option probability
  near_tie_flips         flips whose baseline top two were within NEAR_TIE: rounding, not a different opinion
  errors                 items either side failed to answer
  per_question           the same breakdown per question key, so a regression can be located

Verdict: IDENTICAL (nothing moved) / EQUIVALENT (probabilities moved below the near-tie threshold, no flips) /
CHANGED (a decision flipped, or a probability moved more than the threshold).
"""
import argparse
import json
import math
from pathlib import Path

NEAR_TIE = 0.02  # basal's own threshold (basal/identity.py, basal/agree.py)


def read_answers(path: Path) -> dict[str, dict]:
    """basal-run writes one JSON object per input line, in order. Key them by "id" when present, else by position."""
    out = {}
    for i, line in enumerate(path.read_text(encoding="utf-8").splitlines()):
        if not line.strip():
            continue
        row = json.loads(line)
        out[str(row.get("id", i))] = row
    return out


def probability_vectors(row: dict) -> dict[str, list[float]]:
    """{question key: probabilities in option order}. An errored line yields nothing."""
    answers = row.get("answers")
    if not isinstance(answers, dict):
        return {}
    out = {}
    for key, ans in answers.items():
        probs = ans.get("probabilities") if isinstance(ans, dict) else None
        if isinstance(probs, dict):
            out[key] = [float(v) for v in probs.values()]
    return out


def _gap(x: float, y: float) -> float:
    """A NaN or infinity is the largest possible change, never a skipped comparison (as basal.loadtest does it)."""
    return abs(x - y) if math.isfinite(x) and math.isfinite(y) else 1.0


def _top(probs: list[float]) -> int:
    return max(range(len(probs)), key=probs.__getitem__)


def _near_tie(probs: list[float]) -> bool:
    if len(probs) < 2:
        return False
    first, second = sorted(probs, reverse=True)[:2]
    return (first - second) < NEAR_TIE


def compare_vectors(base: list[float], cand: list[float]) -> dict:
    """One question's two probability vectors. A changed option count is the largest possible difference."""
    if len(base) != len(cand):
        return {"max_abs_dp": 1.0, "flip": True, "near_tie": False, "shape_changed": True}
    return {"max_abs_dp": max((_gap(x, y) for x, y in zip(base, cand)), default=0.0),
            "flip": _top(base) != _top(cand), "near_tie": _near_tie(base), "shape_changed": False}


def _percentile(values: list[float], q: float) -> float:
    """Nearest-rank, as basal-bench computes p95."""
    if not values:
        return 0.0
    ordered = sorted(values)
    return ordered[math.ceil(q * len(ordered)) - 1]


def _blank_bucket() -> dict:
    return {"compared": 0, "identical": 0, "flips": 0, "near_tie_flips": 0, "shape_changed": 0, "dps": []}


def _record(bucket: dict, cmp: dict) -> None:
    bucket["compared"] += 1
    bucket["dps"].append(cmp["max_abs_dp"])
    if cmp["max_abs_dp"] == 0.0:
        bucket["identical"] += 1
    if cmp["flip"]:
        bucket["flips"] += 1
        if cmp["near_tie"]:
            bucket["near_tie_flips"] += 1
    if cmp["shape_changed"]:
        bucket["shape_changed"] += 1


def _summarise(bucket: dict) -> dict:
    dps = bucket.pop("dps")
    return {**bucket, "max_abs_dp": max(dps, default=0.0), "p99_abs_dp": _percentile(dps, 0.99),
            "mean_abs_dp": (sum(dps) / len(dps)) if dps else 0.0}


def verdict(overall: dict) -> str:
    if overall["shape_changed"] or overall["flips"] - overall["near_tie_flips"] > 0:
        return "CHANGED"
    if overall["max_abs_dp"] > NEAR_TIE:
        return "CHANGED"
    if overall["flips"]:
        return "EQUIVALENT"  # only near-tie flips: any change of rounding can move those
    return "IDENTICAL" if overall["identical"] == overall["compared"] else "EQUIVALENT"


def compare(baseline: Path, candidate: Path) -> dict:
    base_rows, cand_rows = read_answers(baseline), read_answers(candidate)
    shared = [k for k in base_rows if k in cand_rows]
    overall, per_question = _blank_bucket(), {}
    errors = []
    for key in shared:
        bv, cv = probability_vectors(base_rows[key]), probability_vectors(cand_rows[key])
        if not bv or not cv:
            errors.append({"id": key, "baseline_error": base_rows[key].get("error"),
                           "candidate_error": cand_rows[key].get("error")})
            continue
        for q in sorted(set(bv) & set(cv)):
            cmp = compare_vectors(bv[q], cv[q])
            _record(overall, cmp)
            _record(per_question.setdefault(q, _blank_bucket()), cmp)
        for q in sorted(set(bv) ^ set(cv)):
            errors.append({"id": key, "question": q, "why": "answered by only one side"})
    summary = _summarise(overall)
    return {"baseline_file": str(baseline), "candidate_file": str(candidate),
            "lines": {"baseline": len(base_rows), "candidate": len(cand_rows), "compared": len(shared),
                      "baseline_only": sorted(set(base_rows) - set(cand_rows))[:20],
                      "candidate_only": sorted(set(cand_rows) - set(base_rows))[:20]},
            "near_tie_threshold": NEAR_TIE, "errors": errors[:50], "error_count": len(errors),
            "overall": summary, "per_question": {q: _summarise(b) for q, b in sorted(per_question.items())},
            "verdict": verdict(summary)}


def main() -> int:
