def test_given_an_exact_tie_when_compared_then_both_sides_break_it_the_same_way(diff):
    """A tie resolved by dict order would read as a flip on one side; the key breaks it deterministically."""
    tie = {"id": "a", "answers": {"q1": {"probabilities": {"x": 0.5, "y": 0.5}}}}
    tie_reordered = {"id": "a", "answers": {"q1": {"probabilities": {"y": 0.5, "x": 0.5}}}}
    result = diff([tie], [tie_reordered])
    assert result["overall"]["flips"] == 0
    assert result["verdict"] == "IDENTICAL"


def test_given_a_noul_answer_when_compared_then_true_false_keys_work(diff):
    """Yes/no questions key on true/false rather than option indices."""
    base = {"id": "a", "answers": {"q": {"probabilities": {"true": 0.9, "false": 0.1}}}}
    cand = {"id": "a", "answers": {"q": {"probabilities": {"true": 0.2, "false": 0.8}}}}
    result = diff([base], [cand])
    assert result["overall"]["flips"] == 1
    assert result["verdict"] == "CHANGED"


def test_given_more_than_ten_options_when_compared_then_ordering_does_not_confuse_the_diff(diff):
    """Keys are "0".."11": lexicographic order differs from numeric, which must not matter."""
    probs = {str(i): 0.1 if i else 0.0 for i in range(12)}
    probs["0"] = 1 - sum(v for k, v in probs.items() if k != "0")
    base = {"id": "a", "answers": {"q": {"probabilities": probs}}}
    cand = {"id": "a", "answers": {"q": {"probabilities": dict(reversed(list(probs.items())))}}}
    result = diff([base], [cand])
    assert result["verdict"] == "IDENTICAL"


