                        "Bash sandbox")
    if "mlx_error" in stack:
        failures.append(f"MLX cannot reach the GPU: {stack['mlx_error']}; run outside the Bash sandbox")
    return failures


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--basal-repo", required=True, type=Path)
    ap.add_argument("--python", default=str(Path.home() / "basal-env/bin/python"))
    ap.add_argument("--benchmarking", action="store_true", help="also apply the gates a measured record needs")
    ap.add_argument("--out", type=Path, default=None)
