"""Running things: worktrees, subprocesses, the served-server lifecycle and weight resolution.

This is the only module that touches the world. Everything it runs is logged in full to the record's raw/ directory,
so a number in a record can always be traced back to the command and output that produced it.
"""
import contextlib
import json
import os
import socket
import subprocess
import time
import urllib.error
import urllib.request
from dataclasses import dataclass
from pathlib import Path

SERVER_READY_TIMEOUT_S = 900  # a cold 4.5B load from a spinning external drive is slow; MLX quantises at load
SERVER_STOP_GRACE_S = 20


@dataclass(frozen=True)
class Result:
    argv: list[str]
    returncode: int
    log: Path

    @property
    def ok(self) -> bool:
        return self.returncode == 0


def run_logged(argv: list[str], cwd: Path, log: Path, env: dict | None = None,
               timeout: int | None = None) -> Result:
    """Run argv, append the command and its combined output to `log`, and return the status without raising."""
    log.parent.mkdir(parents=True, exist_ok=True)
    with log.open("a", encoding="utf-8") as fh:
        fh.write(f"$ cd {cwd} && {' '.join(argv)}\n")
        fh.flush()
        try:
            proc = subprocess.run(argv, cwd=cwd, stdout=fh, stderr=subprocess.STDOUT,
                                  env={**os.environ, **(env or {})}, timeout=timeout)
            code = proc.returncode
        except subprocess.TimeoutExpired:
            fh.write(f"\n[harness] timed out after {timeout}s\n")
            code = 124
        fh.write(f"[harness] exit {code}\n")
    return Result(argv=argv, returncode=code, log=log)


@contextlib.contextmanager
def worktree(repo: Path, sha: str, path: Path):
    """A detached worktree of `sha`, removed afterwards. The repo's own working tree is never checked out or moved."""
    path.parent.mkdir(parents=True, exist_ok=True)
    subprocess.run(["git", "-C", str(repo), "worktree", "add", "--detach", str(path), sha],
                   check=True, capture_output=True, text=True)
    try:
        yield path
    finally:
        subprocess.run(["git", "-C", str(repo), "worktree", "remove", "--force", str(path)],
                       check=False, capture_output=True, text=True)


def resolved_basal(python: str, cwd: Path) -> str:
    """Where `import basal` lands when run from `cwd`. The harness is meaningless unless this is inside cwd."""
    out = subprocess.run([python, "-c", "import basal;print(basal.__file__)"], cwd=cwd,
                         capture_output=True, text=True, timeout=120)
    return out.stdout.strip()


def check_shadowing(python: str, cwd: Path) -> None:
    """Fail loudly if the installed copy of basal wins over the worktree: every metric would describe other code."""
    found = resolved_basal(python, cwd)
    if not found:
        raise RuntimeError(f"could not import basal from {cwd}")
    if not Path(found).resolve().is_relative_to(cwd.resolve()):
        raise RuntimeError(f"import basal resolved to {found}, outside the worktree {cwd}; the venv must hold a "
                           "NON-editable install, and commands must be `python -m basal.<module>`")


def free_port() -> int:
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


def _healthy(url: str) -> bool:
    try:
        with urllib.request.urlopen(url, timeout=5) as r:
            return r.status == 200
    except (urllib.error.URLError, OSError, TimeoutError):
        return False


def server_model_info(base: str) -> dict:
    """GET /v1/models, recorded so a record names the exact weights and engine the answers came from."""
    try:
        with urllib.request.urlopen(f"{base}/v1/models", timeout=15) as r:
            return json.loads(r.read().decode())
    except (urllib.error.URLError, OSError, ValueError, TimeoutError) as e:
        return {"error": f"{type(e).__name__}: {e}"}


@contextlib.contextmanager
def served(argv: list[str], cwd: Path, log: Path, port: int):
    """Start a basal server, wait for /health, yield its base URL, then stop it.

    The server is killed on the way out whatever happened, so a failed phase cannot leave a 9 GB model resident and
    poison the next unit's memory measurements.
    """
    log.parent.mkdir(parents=True, exist_ok=True)
    base = f"http://127.0.0.1:{port}"
    with log.open("a", encoding="utf-8") as fh:
        fh.write(f"$ cd {cwd} && {' '.join(argv)}\n")
        fh.flush()
        proc = subprocess.Popen(argv, cwd=cwd, stdout=fh, stderr=subprocess.STDOUT)
        try:
            deadline = time.monotonic() + SERVER_READY_TIMEOUT_S
            while time.monotonic() < deadline:
                if proc.poll() is not None:
                    raise RuntimeError(f"server exited with {proc.returncode} before becoming ready; see {log}")
                if _healthy(f"{base}/health"):
                    break
                time.sleep(2)
            else:
                raise RuntimeError(f"server did not answer /health within {SERVER_READY_TIMEOUT_S}s; see {log}")
            yield base
        finally:
            proc.terminate()
            try:
                proc.wait(timeout=SERVER_STOP_GRACE_S)
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait(timeout=SERVER_STOP_GRACE_S)
            fh.write(f"[harness] server stopped ({proc.returncode})\n")


def resolve_gguf(repo: str | None, filename: str | None) -> Path | None:
    """The local path of a unit's GGUF file, downloading it if the cache does not have it yet."""
    if not repo or not filename:
        return None
    from huggingface_hub import hf_hub_download
    return Path(hf_hub_download(repo_id=repo, filename=filename))


def ensure_weights(model: str) -> Path:
    """Download a checkpoint if needed and return its local snapshot directory."""
    from huggingface_hub import snapshot_download
    return Path(snapshot_download(repo_id=model))

